487	        submitTest(batchKey, testReq("TK-1", "t1", "FAIL", "i"), null, null, 201);
488	        MvcResult result = mockMvc.perform(get("/api/batches/" + batchKey + "/history"))
489	                .andExpect(status().isOk()).andReturn();
490	        JsonNode node = objectMapper.readTree(result.getResponse().getContentAsString());
491	        assertEquals("REJECTED", node.path("tests").get(0).path("batchStatus").asText());
492	        assertEquals("REJECTED", node.path("batch").path("status").asText());
493	    }
494	
495	    // ---------- helpers ----------
496	
497	    private record CreateCmd(String commandKey, String batchKey, String productCode, String batchNo,
498	                             Instant producedAt, List<String> requiredTests) {
499	    }
500	
501	    private String unique() {
502	        return UUID.randomUUID().toString().substring(0, 8);
503	    }
504	
505	    private String createBody(String batchKey, List<String> items) throws Exception {
506	        return objectMapper.writeValueAsString(new CreateCmd("CK-1", batchKey, "PROD-1", "LOT-1",
507	                Instant.parse("2026-01-02T03:04:05Z"), items));
508	    }
509	
510	    private void createBatch(String batchKey, List<String> items, int expectedStatus) throws Exception {
511	        mockMvc.perform(post("/api/batches")
512	                        .contentType(MediaType.APPLICATION_JSON).content(createBody(batchKey, items)))
513	                .andExpect(status().is(expectedStatus));
