566	        try {
567	            return mockMvc.perform(req).andReturn().getResponse().getStatus();
568	        } catch (Exception e) {
569	            throw new RuntimeException(e);
570	        }
571	    }
572	
573	    @SafeVarargs
574	    private List<Future<Integer>> runConcurrent(Callable<Integer>... tasks) throws Exception {
575	        ExecutorService pool = Executors.newFixedThreadPool(tasks.length);
576	        CyclicBarrier barrier = new CyclicBarrier(tasks.length);
577	        List<Future<Integer>> futures = new ArrayList<>();
578	        for (Callable<Integer> task : tasks) {
579	            futures.add(pool.submit(() -> {
580	                barrier.await(10, TimeUnit.SECONDS);
581	                return task.call();
582	            }));
583	        }
584	        pool.shutdown();
585	        assertTrue(pool.awaitTermination(30, TimeUnit.SECONDS));
586	        return futures;
587	    }
