private LineageEntryResponse toLineageEntry(String key, Map<String,String> parentOf, Set<String> recalled) {
    BatchRepository.BatchRow row = repo.findBatch(key).orElseThrow(...); // should exist
    String blocked = recalledAncestor(key, parentOf, recalled).orElse(null);
    return new LineageEntryResponse(row.batchKey(), row.batchNo(), BatchStatus.valueOf(row.status()), blocked);
}

private Optional<String> recalledAncestor(String batchKey, Map<String,String> parentOf, Set<String> recalled) {
    String current = batchKey;
    while (parentOf.containsKey(current)) {
        current = parentOf.get(current);
        if (recalled.contains(current)) return Optional.of(current);
    }
    return Optional.empty();
}
