private Map<String, String> childToParent() {
    Map<String, String> map = new HashMap<>();
    for (LineageRow row : repo.findAllLineage()) map.put(row.childKey(), row.parentKey());
    return map;
}

private List<String> descendantKeys(String rootKey) {
    // BFS over children map, then sort for deterministic lock order
    Map<String, List<String>> childrenOf = new HashMap<>();
    for (LineageRow row : repo.findAllLineage()) childrenOf.computeIfAbsent(row.parentKey(), k -> new ArrayList<>()).add(row.childKey());
    List<String> result = new ArrayList<>();
    Deque<String> queue = new ArrayDeque<>();
    queue.add(rootKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        for (String child : childrenOf.getOrDefault(current, List.of())) {
            result.add(child);
            queue.add(child);
        }
    }
    Collections.sort(result);
    return result;
}
